"""Links are configured by the owner, never generated by the language model."""
from urllib.parse import urlsplit, urlunsplit


def public_source_url(value):
    if not isinstance(value,str) or len(value)>2000 or any(c.isspace() or ord(c)<32 for c in value):
        return None
    try:
        url=urlsplit(value)
        if (url.scheme!='https' or url.hostname not in {'www.vspu.ru','vspu.ru','files.vspu.ru','portal.vspu.ru','old.vspu.ru'}
                or url.username or url.password or url.port not in (None,443)):
            return None
        return urlunsplit((url.scheme,url.netloc,url.path,url.query,url.fragment))
    except ValueError:
        return None


def source_card(source):
    card={k:source[k] for k in ('source_id','document_id','title','page','locator','ocr')}
    card['source_url']=public_source_url(source.get('source_url'))
    return card
